\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.72\textwidth,
    xmin=0.6, xmax=6.2,
    ymin=0, ymax=1.15,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={1,2,4,6},
    ytick={0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(\displaystyle y=\frac1{x^2}\)}
]
\addplot[domain=1:6, samples=150, fill=gray!18, draw=none] {1/(x^2)} \closedcycle;
\addplot[very thick, domain=0.75:6, samples=200] {1/(x^2)};
\node[anchor=west] at (axis cs:2.3,0.55) {finite area};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.72\textwidth,
    xmin=0.6, xmax=6.2,
    ymin=0, ymax=1.15,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={1,2,4,6},
    ytick={0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={\(\displaystyle y=\frac1x\)}
]
\addplot[domain=1:6, samples=150, fill=gray!18, draw=none] {1/x} \closedcycle;
\addplot[very thick, domain=0.75:6, samples=200] {1/x};
\node[anchor=west] at (axis cs:2.2,0.55) {area keeps growing};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.82\textwidth,
    height=0.48\textwidth,
    xmin=0, xmax=1.05,
    ymin=0, ymax=6,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0,0.25,0.5,0.75,1},
    ytick={0,1,2,4,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, fill=none, at={(0.5,-0.20)}, anchor=north, legend columns=2, font=\small}
]
\addplot[very thick, domain=0.04:1, samples=200] {1/sqrt(x)};
\addlegendentry{\(\displaystyle 1/\sqrt{x}\)}
\addplot[very thick, dashed, domain=0.17:1, samples=200] {1/x};
\addlegendentry{\(\displaystyle 1/x\)}
\node[anchor=east] at (axis cs:0.95,5.0) {\(\displaystyle 1/x\) blows up too strongly};
\node[anchor=west] at (axis cs:0.5,0.85) {\(\displaystyle 1/\sqrt{x}\) is integrable near \(0\)};
\end{axis}
\end{tikzpicture}
